template:
input {
  kafka {
    bootstrap_servers => "__KAFKA_BOOTSTRAP_DHL__"
    topics => [__TOPICS_LIST__]
    group_id => "__GROUP_ID__"
    consumer_threads => __CONSUMER_THREADS__
    codec => json
    decorate_events => true
    auto_create_topics => false
  }
  kafka {
    bootstrap_servers => "__KAFKA_BOOTSTRAP_MLD__"
    topics => [__TOPICS_LIST__]
    group_id => "__GROUP_ID__"
    consumer_threads => __CONSUMER_THREADS__
    codec => json
    decorate_events => true
    auto_create_topics => false
  }
}

filter {
    ruby {
      id => "calculate_event_lag"
      code =>  "
        event.set('event.lag.31.value', ((Time.now.to_f - event.get('@timestamp').to_f) * 1000).round);
        event.set('event.lag.31.label', execution_context.pipeline.pipeline_id)
      "
    }
    ruby {
      init => "require 'socket'; @hostname = Socket.gethostname.split('.').first"
      code => "event.tag(@hostname)"
    }

    if [@metadata][dead_letter_queue][reason] {
      mutate {
        rename => {
          "[@metadata][dead_letter_queue][reason]" => "[dlq][reason]"
        }
      }
    }
}

output {
  if [@metadata][kafka][topic] == "filebeat" {
    elasticsearch {
      hosts => [__ES_HOSTS__]
      index => "filebeat-%{[agent][version]}"
      manage_template => false
      pipeline => "%{[@metadata][pipeline]}"
      action => "create"
      id => "${VAR_CLIENT_ID}"
      ssl_enabled => true
      ssl_verification_mode => "none"
      api_key => "${VAR_API_KEY}"
    }
  } else {
    elasticsearch {
      hosts => [__ES_HOSTS__]
      data_stream => true
      ssl_enabled => true
      ssl_verification_mode => "none"
      api_key => "${VAR_API_KEY}"
    }
  }
}
